# adapta las instrucciones a varias aperturas diarias sin explicar la estructura interna al empleado
$chapters[24].body = '<p>Desde Panel principal, presioná Caja y gastos. Elegí la fecha y, en Caja / turno, seleccioná la apertura que querés consultar. Cada caja muestra únicamente sus propios cobros, ingresos y gastos.</p><h2>Abrir la primera caja</h2><ol><li>Seleccioná la fecha de hoy.</li><li>Si todavía no hay una apertura, completá Saldo inicial ARS, Saldo inicial USD y las observaciones necesarias.</li><li>Presioná Abrir caja. La hora se registra automáticamente.</li><li>Comprobá el número de caja abierta antes de empezar a cobrar.</li></ol><p>Solo puede haber una caja abierta a la vez. La comparten los operadores y debe estar abierta antes de registrar ventas, cobros o movimientos manuales.</p><h2>Registrar un movimiento manual</h2><ol><li>Seleccioná la caja abierta de hoy.</li><li>Elegí el tipo: Gasto, Ingreso extra o Café.</li><li>Completá concepto, medio, moneda, importe y cuenta o referencia cuando corresponda.</li><li>Presioná Registrar y revisá el listado y los totales.</li></ol><p>Los cobros de ventas aparecen automáticamente y se suman sin recargo. No los registres otra vez como ingreso extra. Los pesos y dólares se muestran separados; los movimientos en dólares se registran en efectivo.</p>'
$chapters[26].body = '<h2>Cerrar la caja seleccionada</h2><ol><li>Seleccioná la fecha y la caja que sigue abierta.</li><li>Presioná Consultar / actualizar y revisá cobros, ingresos, gastos, saldos iniciales y observaciones.</li><li>Coordiná con los otros operadores para que terminen sus operaciones.</li><li>Presioná Cerrar caja seleccionada y leé la confirmación.</li><li>Confirmá solamente si los importes son correctos. Esa caja no admitirá nuevas operaciones.</li></ol><h2>Continuar trabajando el mismo día</h2><ol><li>Con el cierre seleccionado, presioná Nueva caja.</li><li>Completá los saldos iniciales del nuevo turno. No se copian automáticamente del cierre anterior.</li><li>Presioná Abrir caja y comprobá el nuevo número.</li></ol><p>Mientras no abras otra caja, no se pueden registrar nuevos cobros ni movimientos. Podés cerrar y abrir varias cajas en la misma fecha, pero no mantener dos abiertas simultáneamente.</p><h2>Consultar e imprimir</h2><p>Elegí la fecha y el número de caja en Caja / turno. Presioná Ver / imprimir cierre para abrir el documento de esa apertura. Dos cierres del mismo día tienen números distintos y no reemplazan sus documentos entre sí.</p><h2>Cambio de día</h2><p>Si una caja sigue abierta al cambiar la fecha, se cierra automáticamente. Si Prana estaba apagado, completa ese cierre al iniciar. Después debés abrir la caja del nuevo día para operar. Los cierres automáticos se identifican como CIERRE AUTOMÁTICO.</p>'
$chapters[27].body += '<p>Puede haber varios cierres por fecha. El resumen mensual cuenta cada cobro y movimiento una sola vez y no suma los saldos iniciales como ingresos.</p>'
foreach ($capitulo in $chapters) {
    $capitulo.body = $capitulo.body.Replace('no se podrán agregar más cobros ni movimientos a esa fecha', 'no se podrán agregar más cobros ni movimientos a esa caja')
    $capitulo.body = $capitulo.body.Replace('no se pueden registrar más movimientos para esa fecha', 'no se pueden registrar más movimientos en esa caja; abrí otra para continuar')
}
